// Replaced at build time by `define` in vite.config.ts. Declared here so `src` sees
// them as real values rather than stray identifiers — they are substituted textually,
// so they exist in the bundle but never in the source.
declare const __FF_VERSION__: string
declare const __FF_COMMIT__: string
declare const __FF_BUILT_AT__: string
